// Standalone JUCE module build for the BuiltInFx tests.
//
// This file exists only so tests/BuiltInFxTests.cpp can be built and run
// without the full OpenMix app (and without rnnoise, whose Linux test link
// is known-broken). It compiles the two JUCE modules the effects need
// (juce_core + juce_audio_basics) as a single translation unit, and defines
// the juce_compilationDate / juce_compilationTime symbols that juce_core
// expects the host application to provide (normally generated by CMake).
//
// Build + run from the repo root (takes ~30 s, almost all of it JUCE):
//   g++ -std=c++20 -O2 -I Source -I external/JUCE/modules \
//     -DJUCE_USE_CURL=0 -DJUCE_WEB_BROWSER=0 -DJUCE_GLOBAL_MODULE_SETTINGS_INCLUDED=1 \
//     tests/BuiltInFxTests.cpp tests/JuceModules.cpp Source/dsp/BuiltInFx.cpp \
//     -lpthread -ldl -lz -o /tmp/BuiltInFxTests && /tmp/BuiltInFxTests

#include <juce_core/juce_core.cpp>
#include <juce_audio_basics/juce_audio_basics.cpp>

namespace juce
{
    const char* juce_compilationDate = __DATE__;
    const char* juce_compilationTime = __TIME__;
}
